<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login();$rows=$pdo->query("SELECT p.*,b.bill_no,u.full_name FROM payments p JOIN bills b ON b.id=p.bill_id JOIN users u ON u.id=p.cashier_id ORDER BY p.id DESC")->fetchAll();?><!doctype html><html lang="sw"><head><meta charset="utf-8"><title>Receipts Zote</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="container"><div class="text-center"><h2>RESTAURANT - RECEIPTS REPORT</h2><p><?=date('Y-m-d H:i')?></p></div><table><tr><th>#</th><th>Receipt</th><th>Bill</th><th>Amount</th><th>Method</th><th>Cashier</th><th>Tarehe</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['receipt_no'])?></td><td><?=e($r['bill_no'])?></td><td><?=number_format($r['amount'],2)?></td><td><?=e($r['method'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['paid_at'])?></td></tr><?php endforeach;?></table><div class="actions no-print"><button onclick="window.print()">Print</button></div></div></body></html>
